  if (delta_yaw > rad_pi) {
    delta_yaw = delta_yaw - rad_round;
  }
  if (delta_yaw < -rad_pi) {
    delta_yaw = delta_yaw + rad_round;

  t = frame_3.get_byte(0, 8);
  value <<= 8;
  value |= t;

  if (value > 0x3FFFFFFF) {
    value -= 0x80000000;
  }

  return value * (1.000000 / 3.000000) * 1e-6;
}

