  /**
   * @brief get hours from byte array
   * config detail: {'name': 'hours', 'offset': 0.0, 'precision': 1.0, 'len': 5,
   * 'f_type': 'value', 'is_signed_var': False, 'physical_range': '[0|23]',
   * 'bit': 24, 'type': 'int', 'order': 'intel', 'physical_unit': '"hours"'}
