  pedal_enable_ = false;
  clear_driver_override_flag_ = false;
  ignore_driver_override_ = false;

bool GLFWViewer::Initialize() {
  AINFO << "GLFWViewer::initialize()" << std::endl;
  if (init_) {
    AINFO << " GLFWViewer is already initialized !" << std::endl;
    return false;
  }

  if (!WindowInit()) {
    AINFO << " Failed to initialize the window !" << std::endl;
    return false;
  }

  if (!CameraInit()) {
    AINFO << " Failed to initialize the camera !" << std::endl;
    return false;
  }

  if (!OpenglInit()) {
    AINFO << " Failed to initialize opengl !" << std::endl;
    return false;
  }

  init_ = true;

  if (!_rtcm_parser) {
    ROS_ERROR("Failed to create rtcm parser.");
    return false;
  }

  _inited_flag = true;
  return true;
}

