for (auto& lane : feature->lane().current_lane_feature()) {
  std::shared_ptr<const LaneInfo> lane_info =
      PredictionMap::LaneById(lane.lane_id());
  const LaneGraph& lane_graph = ObstacleClusters::GetLaneGraph(
