void LocalizationIntegImpl::ImuThreadLoop() {
  AINFO << "Started imu data process thread";
  while (keep_imu_running_.load()) {
    {
      std::unique_lock<std::mutex> lock(imu_data_queue_mutex_);
      size_t size = imu_data_queue_.size();
      while (size > imu_queue_max_size_) {
        imu_data_queue_.pop();
        --size;
      }
      if (imu_data_queue_.size() == 0) {
        imu_data_signal_.wait(lock);
        continue;
      }
    }

    ImuData imu_data;
    int waiting_num = 0;
    {
      std::unique_lock<std::mutex> lock(imu_data_queue_mutex_);
      imu_data = imu_data_queue_.front();
      imu_data_queue_.pop();
      waiting_num = imu_data_queue_.size();
    }

    if (waiting_num > 10) {

    Eigen::Vector4d scn_center_(scn_center(0), scn_center(1), scn_center(2), 1);
    scn_center_ = mode_mat_ * view_mat_ * scn_center_;
    scn_center = scn_center_.head(3);
    Eigen::Vector3d r_multi_scn_center = rot_mat * scn_center;
    Eigen::Vector3d t = scn_center - r_multi_scn_center;
    Eigen::Matrix4d cur_mat = Eigen::Matrix4d::Identity();
    cur_mat.topLeftCorner(3, 3) = rot_mat;
    cur_mat.topRightCorner(3, 1) = t;
    mode_mat_ = cur_mat * mode_mat_;
  } else if (state_right == GLFW_PRESS) {
    mode_mat_(0, 3) += 0.1 * x_delta;
    mode_mat_(1, 3) -= 0.1 * y_delta;
  }

  mouse_prev_x_ = xpos;
  mouse_prev_y_ = ypos;
}

