void TopoNode::AddOutEdge(const TopoEdge* edge) {
  if (edge->FromNode() != this) {
    return;
  }
  if (out_edge_map_.count(edge->ToNode()) != 0) {
    return;
  }
  switch (edge->Type()) {
    case TET_LEFT:
      out_to_left_edge_set_.insert(edge);
      out_to_left_or_right_edge_set_.insert(edge);
      break;
    case TET_RIGHT:
      out_to_right_edge_set_.insert(edge);
      out_to_left_or_right_edge_set_.insert(edge);
      break;
    default:
      out_to_suc_edge_set_.insert(edge);
      break;
  }
  out_to_all_edge_set_.insert(edge);
  out_edge_map_[edge->ToNode()] = edge;

glMatrixMode(GL_PROJECTION);  // Operate on projection matrix
glLoadIdentity();
glOrtho(scene_width_, scene_width_ + image_width_, image_height_, 0.0, 0.0,
        100.0);

glMatrixMode(GL_MODELVIEW);  // Operate on model-view matrix
glLoadIdentity();

glEnable(GL_TEXTURE_2D);
GLuint image_tex = image_to_gl_texture(image_mat_src, GL_LINEAR_MIPMAP_LINEAR,
                                       GL_LINEAR, GL_CLAMP);

/* Draw a quad */
glBegin(GL_QUADS);
glTexCoord2i(0, 0);
glVertex2i(scene_width_, 0);
glTexCoord2i(0, 1);
glVertex2i(scene_width_, image_height_);
glTexCoord2i(1, 1);
glVertex2i(scene_width_ + image_width_, image_height_);
glTexCoord2i(1, 0);
glVertex2i(scene_width_ + image_width_, 0);
glEnd();

glDeleteTextures(1, &image_tex);
glDisable(GL_TEXTURE_2D);

LaneWaypoint RightNeighborWaypoint(const LaneWaypoint& waypoint) {
  LaneWaypoint neighbor;
  if (!waypoint.lane) {
    return neighbor;
  }
  auto point = waypoint.lane->GetSmoothPoint(waypoint.s);
  auto map_ptr = HDMapUtil::BaseMapPtr();
  for (const auto& lane_id :
       waypoint.lane->lane().right_neighbor_forward_lane_id()) {
    auto lane = map_ptr->GetLaneById(lane_id);
    if (!lane) {
      return neighbor;
    }
    double s = 0.0;
    double l = 0.0;
    if (!lane->GetProjection({point.x(), point.y()}, &s, &l)) {
      continue;
    }
    if (s < -kSampleDistance || s > lane->total_length() + kSampleDistance) {
      continue;
    } else {
      return LaneWaypoint(lane, s);
    }
  }
  return neighbor;

  return right_out_sorted_range_;
}

