// config detail: {'name': 'feat_base_trial', 'offset': 0.0, 'precision': 1.0,
// 'len': 1, 'f_type': 'valid', 'is_signed_var': False, 'physical_range':
// '[0|0]', 'bit': 17, 'type': 'bool', 'order': 'intel', 'physical_unit': '""'}
bool License7e::is_feat_base_trial(const std::uint8_t* bytes,
                                   int length) const {
  Byte frame(bytes + 2);

  const auto& boundary = path_obstacle.st_boundary();
  const double fence_s =
      adc_sl_boundary_.end_s() + boundary.min_s() + stop_distance;
  const double main_stop_s =
      reference_line_info_->path_decision()->stop_reference_line_s();
  if (main_stop_s < fence_s) {
    ADEBUG << "Stop fence is further away, ignore.";
    return false;
  }

  const auto fence_point = reference_line_->GetReferencePoint(fence_s);

  // set STOP decision
  auto* stop = stop_decision->mutable_stop();
  stop->set_distance_s(stop_distance);
  auto* stop_point = stop->mutable_stop_point();
  stop_point->set_x(fence_point.x());
  stop_point->set_y(fence_point.y());
  stop_point->set_z(0.0);
  stop->set_stop_heading(fence_point.heading());

  PerceptionObstacle::Type obstacle_type =
      path_obstacle.obstacle()->Perception().type();
  ADEBUG << "STOP: obstacle_id[" << path_obstacle.obstacle()->Id()
         << "] obstacle_type[" << PerceptionObstacle_Type_Name(obstacle_type)
         << "]";

  return true;
}

bool SpeedDecider::CreateFollowDecision(
    const PathObstacle& path_obstacle,
    ObjectDecisionType* const follow_decision) const {
  DCHECK_NOTNULL(follow_decision);

  AddSendProtocolData<Turncmd63, true>();
  AddSendProtocolData<Wipercmd90, true>();

  // Report Messages
  AddRecvProtocolData<Accelrpt68, true>();
  AddRecvProtocolData<Brakemotorrpt170, true>();
  AddRecvProtocolData<Brakemotorrpt271, true>();
  AddRecvProtocolData<Brakemotorrpt372, true>();
  AddRecvProtocolData<Brakerpt6c, true>();
  AddRecvProtocolData<Datetimerpt83, true>();
  AddRecvProtocolData<Globalrpt6a, true>();
  AddRecvProtocolData<Headlightrpt77, true>();
  AddRecvProtocolData<Hornrpt79, true>();
  AddRecvProtocolData<Latlonheadingrpt82, true>();
  AddRecvProtocolData<Parkingbrakestatusrpt80, true>();
  AddRecvProtocolData<Shiftrpt66, true>();
  AddRecvProtocolData<Steeringmotorrpt173, true>();
  AddRecvProtocolData<Steeringmotorrpt274, true>();
  AddRecvProtocolData<Steeringmotorrpt375, true>();
  AddRecvProtocolData<Steeringrpt16e, true>();
  AddRecvProtocolData<Turnrpt64, true>();
  AddRecvProtocolData<Vehiclespeedrpt6f, true>();
  AddRecvProtocolData<Wheelspeedrpt7a, true>();
  AddRecvProtocolData<Wiperrpt91, true>();
  AddRecvProtocolData<Yawraterpt81, true>();
}

