int ObjectQualityInfo60C::longitude_accel_rms(const std::uint8_t* bytes,
                                              int32_t length) const {
  Byte t0(bytes + 3);
  int32_t x = t0.get_byte(0, 4);

  std::uint8_t t = 0;
  t = x & 0xFF;  // low
  Byte frame_low(data + 0);
  frame_low.set_value(t, 0, 8);

  x >>= 8;  // high
  t = x & 0xFF;
  Byte frame_high(data + 1);
  frame_high.set_value(t, 0, 8);
}

void Steering64::set_enable_p(uint8_t *bytes, bool enable) {
  Byte frame(bytes + 2);
  if (enable) {
    frame.set_bit_1(0);
  } else {
    frame.set_bit_0(0);
  }
}

void Steering64::set_clear_driver_override_flag_p(uint8_t *bytes, bool clear) {
  Byte frame(bytes + 2);
  if (clear) {
    frame.set_bit_1(1);
  } else {
    frame.set_bit_0(1);
  }
}

void Steering64::set_ignore_driver_override_p(uint8_t *bytes, bool ignore) {
  Byte frame(bytes + 2);
  if (ignore) {
    frame.set_bit_1(2);
  } else {
    frame.set_bit_0(2);
  }
}

