mmon::PointENU& point, double distance, std::vector<YieldSignInfoConstPtr>* yield_signs) const; /** * @brief get all clear areas in certain range * @param point the central point of the range * @param distance the search radius * @param clear_areas store all clear areas in target range * @return 0:success, otherwise failed */ int GetClearAreas(const apollo::common::PointENU& point, double distance, std::vector<ClearAreaInfoConstPtr>* clear_areas) const; /** * @brief get all speed bumps in certain range * @param point the central point of the range * @param distance the search radius * @param speed_bumps store all speed bumps in target range * @return 0:success, otherwise failed */ int GetSpeedBumps(const apollo::common::PointENU& point, double distance, std::vector<SpeedBumpInfoConstPtr>* speed_bumps) const; /** * @brief get all roads in certain range * @param point the central point of the range * @param distance the search radius * @param roads store all roads in target range * @return 0:success, otherwise failed */ int GetRoads(const apollo::common::PointENU& point, double distance, std::vector<RoadInfoConstPtr>* roads) const; /** * @brief get nearest lane from target point, * @param point the target point * @param nearest_lane the nearest lane that match search conditions * @param nearest_s the offset from lane start point along lane center line * @param nearest_l the lateral offset from lane center line * @return 0:success, otherwise, failed. */ int GetNearestLane(const apollo::common::PointENU& point, LaneInfoConstPtr* nearest_lane, double* nearest_s, double* nearest_l) const; /** * @brief get the nearest lane within a certain range by pose * @param point the target position * @param distance the search radius * @param central_heading the base heading * @param max_heading_difference the heading range * @param nearest_lane the nearest lane that match search conditions * @param nearest_s the offset from lane start point along lane center line * @param nearest_l 