class StopSignInfo {
 public:
  explicit StopSignInfo(const StopSign &stop_sign);

  const Id &id() const { return stop_sign_.id(); }
  const StopSign &stop_sign() const { return stop_sign_; }
  const std::vector<apollo::common::math::LineSegment2d> &segments() const {
    return segments_;

Eigen::Vector2d position(feature.position().x(), feature.position().y());
double speed = feature.speed();

int lane_segment_index = 0;
std::string lane_id =
    lane_sequence.lane_segment(lane_segment_index).lane_id();
std::shared_ptr<const LaneInfo> lane_info = PredictionMap::LaneById(lane_id);
double lane_s = 0.0;
double lane_l = 0.0;
if (!PredictionMap::GetProjection(position, lane_info, &lane_s, &lane_l)) {
  AERROR << "Failed in getting lane s and lane l";
  return;
}
size_t total_num = static_cast<size_t>(total_time / period);
for (size_t i = 0; i < total_num; ++i) {
  double relative_time = static_cast<double>(i) * period;
  Eigen::Vector2d point;
  double theta = M_PI;
  if (!PredictionMap::SmoothPointFromLane(lane_id, lane_s, lane_l, &point,
                                          &theta)) {
    AERROR << "Unable to get smooth point from lane [" << lane_id
           << "] with s [" << lane_s << "] and l [" << lane_l << "]";
    break;
  }
  TrajectoryPoint trajectory_point;
  PathPoint path_point;
  path_point.set_x(point.x());
  path_point.set_y(point.y());
  path_point.set_z(0.0);
  path_point.set_theta(theta);
  path_point.set_lane_id(lane_id);
  trajectory_point.mutable_path_point()->CopyFrom(path_point);
  trajectory_point.set_v(speed);
  trajectory_point.set_a(0.0);
  trajectory_point.set_relative_time(relative_time);
  points->emplace_back(std::move(trajectory_point));

  lane_s += speed * period;

  while (lane_s > PredictionMap::LaneById(lane_id)->total_length() &&
         lane_segment_index + 1 < lane_sequence.lane_segment_size()) {
    lane_segment_index += 1;
    lane_s = lane_s - PredictionMap::LaneById(lane_id)->total_length();
    lane_id = lane_sequence.lane_segment(lane_segment_index).lane_id();
  }

  lane_l *= FLAGS_go_approach_rate;

  chassis->mutable_gem()->mutable_steering_motor_rpt_2_74()->set_angular_speed(
      angular_speed(bytes, length));
}

